mapper.select:
select
ad.ASSETS_DISPOSAL_ID, ad.ASSETS_APPL_NUMBER, ad.APPROVAL_STATUS, ad.EMPLOYEE_ID, ad.PROJECT_ID, ad.FINANCE_AMOUNT, p.CONTRACT_AMOUNT, ad.FROM_DATE, ad.TO_DATE, ad.CONTRACT_NUMBER, ad.START_DATE,
(SELECT meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CREDIT.APPROVE_STATUS' AND v.code_value = ad.APPROVAL_STATUS)APPROVAL_STATUS_N, p.CONTRACT_STATUS, (SELECT meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CON.CONTRACT_STATUS' AND v.code_value = p.CONTRACT_STATUS)CONTRACT_STATUS_N, (SELECT em.name FROM fnd_employee em where em.employee_id = ad.EMPLOYEE_ID) EMPLOYEE_ID_N,
p.PROJECT_NUMBER, p.TENANT_ID, CASE WHEN p.BUSINESS_TYPE in('T+N_LEASE_FACTORING','T+0_LEASE_FACTORING') THEN ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE p.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'RECEIVABLE_DEBTOR' ) WHEN p.BUSINESS_TYPE in('LEASE_WITHOUT_RECOURSE_IN','OPERATING_LEASE_WITHOUT_RECOURSE_IN') THEN ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE p.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'ASSET_TRANSFEROR' ) ELSE ( SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE p.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'TENANT' ) END AS tenant_id_n,
-- ( -- SELECT -- b.bp_name -- FROM -- hls_bp_master b -- WHERE -- b.bp_id = p.tenant_id -- ) tenant_id_n, (select nvl(max(f.OVERDUE_MAX_DAYS),0) from con_contract c,con_contract_cashflow f where c.CONTRACT_ID = f.CONTRACT_ID and c.PROJECT_ID = p.PROJECT_ID) OVERDUE_MAX_DAYS, (select nvl(sum(f.OVERDUE_AMOUNT),0) from con_contract c,con_contract_cashflow f where c.CONTRACT_ID = f.CONTRACT_ID and c.PROJECT_ID = p.PROJECT_ID) OVERDUE_AMOUNT from assets_disposal ad,prj_project p
ad.PROJECT_ID = p.PROJECT_ID and p.DATA_CLASS = 'VIRTUAL_CON'
and (p.created_by = #{createdBy} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE = 'ADMIN' and U.USER_ID = #{createdBy}))
and ad.ASSETS_APPL_NUMBER = #{assetsApplNumber}
and p.PROJECT_NUMBER = #{projectNumber}
and ad.CONTRACT_NUMBER = #{contractNumber}
and ad.EMPLOYEE_ID = #{employeeId}
and p.TENANT_ID = #{tenantId}
and ad.ASSETS_DISPOSAL_ID = #{assetsDisposalId}
and ad.APPROVAL_STATUS = #{approvalStatus}
and ad.FROM_DATE between #{startDate} and #{toDate}
order by ad.ASSETS_DISPOSAL_ID desc
